// Do not edit this file as it will be overwritten if HAMR codegen is rerun

use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_error_status: bool,
}

/// container for component's incoming port values and GUMBO state variables
pub struct PreStateContainer_wGSV {
  pub In_retained_mode: open_platform_Data_Model::OperatingMode,
  pub api_error_status: bool,
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_error_status(container.api_error_status);
}

/// setter for component's incoming port values and GUMBO state variables
pub fn put_concrete_inputs_container_wGSV(container: PreStateContainer_wGSV)
{
  put_retained_mode(container.In_retained_mode);
  put_error_status(container.api_error_status);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(error_status: bool)
{
  put_error_status(error_status);
}

/// setter for component's incoming port values and GUMBO state variables
pub fn put_concrete_inputs_wGSV(
  In_retained_mode: open_platform_Data_Model::OperatingMode,
  error_status: bool)
{
  put_retained_mode(In_retained_mode);
  put_error_status(error_status);
}

/// setter for IN DataPort
pub fn put_error_status(value: bool)
{
  *extern_api::IN_error_status.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_mode_to_rx() -> open_platform_Data_Model::OperatingMode
{
  return extern_api::OUT_mode_to_rx.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}

/// getter for OUT DataPort
pub fn get_mode_to_mavlink() -> open_platform_Data_Model::OperatingMode
{
  return extern_api::OUT_mode_to_mavlink.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}

/// getter for GUMBO State Variable
pub fn get_retained_mode() -> open_platform_Data_Model::OperatingMode
{
  unsafe {
    match &crate::app {
      Some(inner) => inner.retained_mode,
      None => panic!("The app is None")
    }
  }
}

/// setter for GUMBO State Variable
pub fn put_retained_mode(value: open_platform_Data_Model::OperatingMode)
{
  unsafe {
    match &mut crate::app {
      Some(inner) => inner.retained_mode = value,
      None => panic!("The app is None")
    }
  }
}
